-- AI/ML pathway ("Cipher Division") Act 12 -- "Feature Forge" content.
-- Closes Arc II ("Machines That Predict", Acts 7-12). Arjun Vale leads:
-- one real, leakage-safe, end-to-end feature pipeline built to finally act
-- on the unlabeled cluster Act 11 discovered ("Cluster Zero"), before the
-- pathway pivots into deep learning next Act.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other pathway. World/act/pathway
-- rows already exist (world-ai-feature-forge, act-ai-2) and are not touched.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-feature-forge', 'world-ai-feature-forge', 'feature-forge', '12A - Feature Forge', 'Turn raw fields from Echo''s interaction log into leakage-safe, production-grade features, then assemble every technique into one real end-to-end pipeline before this Arc closes.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-feature-forge-1', 'campaign-ai-feature-forge', 'raw-into-useful', 'Raw Into Useful', 'Numeric transforms, categorical encoding, interaction features, time features and text features -- turning raw log fields into inputs a model can actually learn from.', 1),
  ('operation-ai-feature-forge-2', 'campaign-ai-feature-forge', 'one-real-system', 'One Real System', 'Missing indicators, feature selection, leakage-safe pipelines, scikit-learn Pipelines and one end-to-end system, assembled into Cipher Division''s first production-shaped pipeline.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-feature-forge-01', 'world-ai-feature-forge', 'campaign-ai-feature-forge', 'operation-ai-feature-forge-1', 'feature-engineering', 'Feature Engineering', 'Act 11 found a real cluster with no explanation. Arjun wants one proper, end-to-end feature pipeline before this Arc closes -- not another one-off notebook.', 'beginner', ARRAY['maya','arjun'], null, null, '{"type":"simulation","simulationId":"feature-engineering-intro-sim"}'::jsonb, '{"xp":230,"credits":50}'::jsonb, false, 1),
  ('mission-ai-feature-forge-02', 'world-ai-feature-forge', 'campaign-ai-feature-forge', 'operation-ai-feature-forge-1', 'numeric-transformations', 'Numeric Transformations', 'Raw numbers rarely arrive in a shape a model can use well. Numeric transformations reshape scale and skew without changing what a value means.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-feature-forge-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"numeric-transform-sim"}'::jsonb, '{"xp":240,"credits":55}'::jsonb, false, 2),
  ('mission-ai-feature-forge-03', 'world-ai-feature-forge', 'campaign-ai-feature-forge', 'operation-ai-feature-forge-1', 'categorical-features', 'Categorical Features', 'Categories are not numbers until encoding makes them one -- and the wrong encoding invents an order that was never really there.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-feature-forge-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"categorical-encoding-sim"}'::jsonb, '{"xp":240,"credits":55}'::jsonb, false, 3),
  ('mission-ai-feature-forge-04', 'world-ai-feature-forge', 'campaign-ai-feature-forge', 'operation-ai-feature-forge-1', 'interaction-features', 'Interaction Features', 'Some signal only exists in the relationship between two features, not in either one alone. Interaction features capture it on purpose.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-feature-forge-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"interaction-features-sim"}'::jsonb, '{"xp":250,"credits":55}'::jsonb, false, 4),
  ('mission-ai-feature-forge-05', 'world-ai-feature-forge', 'campaign-ai-feature-forge', 'operation-ai-feature-forge-1', 'time-features', 'Time Features', 'A timestamp is useless until it becomes hour of day, day of week, and time since something else happened.', 'intermediate', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-feature-forge-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"time-features-sim"}'::jsonb, '{"xp":250,"credits":60}'::jsonb, false, 5),
  ('mission-ai-feature-forge-06', 'world-ai-feature-forge', 'campaign-ai-feature-forge', 'operation-ai-feature-forge-1', 'text-features', 'Text Features', 'Free text is not a feature until length, keywords and term frequency turn it into numbers a model can compare.', 'intermediate', ARRAY['arjun','byte'], '{"requiredMissionIds":["mission-ai-feature-forge-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"text-features-sim"}'::jsonb, '{"xp":260,"credits":60}'::jsonb, false, 6),
  ('mission-ai-feature-forge-07', 'world-ai-feature-forge', 'campaign-ai-feature-forge', 'operation-ai-feature-forge-2', 'missing-indicators', 'Missing Indicators', 'A missing value can mean something. Silently filling it in erases exactly the signal an explicit indicator would keep.', 'intermediate', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-feature-forge-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"missing-indicators-sim"}'::jsonb, '{"xp":260,"credits":60}'::jsonb, false, 7),
  ('mission-ai-feature-forge-08', 'world-ai-feature-forge', 'campaign-ai-feature-forge', 'operation-ai-feature-forge-2', 'feature-selection', 'Feature Selection', 'More features is not automatically better. Redundant and irrelevant columns cost signal, not add it -- and one careless line can leak the answer straight back in.', 'intermediate', ARRAY['arjun','byte'], '{"requiredMissionIds":["mission-ai-feature-forge-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"feature-selection-sim"}'::jsonb, '{"xp":270,"credits":65}'::jsonb, false, 8),
  ('mission-ai-feature-forge-09', 'world-ai-feature-forge', 'campaign-ai-feature-forge', 'operation-ai-feature-forge-2', 'leakage-safe-pipelines', 'Leakage-Safe Pipelines', 'Leakage is the single most dangerous mistake in this whole pipeline: information the model should never have had at prediction time, smuggled in by accident.', 'intermediate', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-feature-forge-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"leakage-safe-pipeline-sim"}'::jsonb, '{"xp":270,"credits":65}'::jsonb, false, 9),
  ('mission-ai-feature-forge-10', 'world-ai-feature-forge', 'campaign-ai-feature-forge', 'operation-ai-feature-forge-2', 'scikit-learn-pipelines', 'scikit-learn Pipelines', 'Every technique this Act taught has to run in the same order, the same way, every time -- scikit-learn''s Pipeline is how that gets guaranteed instead of hoped for.', 'intermediate', ARRAY['arjun','byte'], '{"requiredMissionIds":["mission-ai-feature-forge-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"sklearn-pipeline-sim"}'::jsonb, '{"xp":280,"credits":65}'::jsonb, false, 10),
  ('mission-ai-feature-forge-11', 'world-ai-feature-forge', 'campaign-ai-feature-forge', 'operation-ai-feature-forge-2', 'end-to-end-ml', 'End-to-End ML', 'Raw log in, leakage-safe features out, a model trained and evaluated honestly, and a result that reproduces on the next run -- the whole Act, assembled into one real system.', 'intermediate', ARRAY['arjun','byte'], '{"requiredMissionIds":["mission-ai-feature-forge-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"end-to-end-ml-sim"}'::jsonb, '{"xp":280,"credits":70}'::jsonb, false, 11),
  ('mission-ai-feature-forge-12', 'world-ai-feature-forge', 'campaign-ai-feature-forge', 'operation-ai-feature-forge-2', 'the-prediction-engine', 'The Prediction Engine', 'Cipher Division''s first genuinely production-shaped system, tested against everything that could make it a lie: leakage, irreproducibility, and whether it actually catches what Act 11 found.', 'boss', ARRAY['maya','arjun'], '{"requiredMissionIds":["mission-ai-feature-forge-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"prediction-engine-boss-sim"}'::jsonb, '{"xp":720,"credits":160,"badgeIds":["the-prediction-engine"],"skillXp":{"feature_engineering":55,"ai_ml_fundamentals":20}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-feature-forge-01', 1, 'maya', 'Arc II closes with this Act. Before Cipher Division hands the harder half of this investigation to deep learning, there is one thing we have never actually built end to end: a real, trustworthy feature pipeline.'),
  ('mission-ai-feature-forge-01', 2, 'maya', 'Act 11 found something real -- a small, distinct cluster of Echo''s interactions that does not match anything we have ever categorized. It is sitting in the database right now, completely unusable, because nobody can act on raw log fields.'),
  ('mission-ai-feature-forge-01', 3, 'arjun', 'Arjun Vale, data engineering -- back for the send-off. A raw field is whatever a system happened to log: a timestamp string, a status code, a block of free text. A feature is something a model can actually learn from. Those are not the same thing, and the distance between them is my entire job.'),
  ('mission-ai-feature-forge-01', 4, 'arjun', 'Feature engineering is the discipline of closing that distance -- transforming, combining and reshaping raw data into inputs that carry real signal. By the end of this Act we assemble one real pipeline, and that pipeline is what finally lets us act on what Act 11 found. Cipher Division has started calling it Cluster Zero.'),

  ('mission-ai-feature-forge-02', 1, 'arjun', 'Cluster Zero''s request counts are heavily skewed -- most sessions send a handful of requests, a few send thousands. Feed that straight into most models and the huge values dominate everything else.'),
  ('mission-ai-feature-forge-02', 2, 'arjun', 'Numeric transformations reshape a raw number''s distribution or scale without changing what it means: log transforms compress skew, scaling and normalization put features on comparable ranges, and binning turns a continuous value into ordered buckets.'),
  ('mission-ai-feature-forge-02', 3, 'arjun', 'Pick the wrong transform and you either drown the model in outliers or throw away the exact pattern you are trying to find.'),

  ('mission-ai-feature-forge-03', 1, 'arjun', 'Echo''s log also carries categorical fields -- interaction_type, region, device_class -- values from a fixed set rather than numbers. Models still need numbers, so categories have to be encoded, not just labeled and hoped for.'),
  ('mission-ai-feature-forge-03', 2, 'arjun', 'One-hot encoding turns each category into its own 0/1 column, with no implied order -- correct for something like region. Ordinal encoding assigns an order, like low, medium, high severity, which is only correct when the categories actually have a real order.'),
  ('mission-ai-feature-forge-03', 3, 'arjun', 'Use ordinal encoding on a field with no real order and the model quietly learns a ranking that does not exist. That mistake is subtle, and it is everywhere in badly engineered pipelines.'),

  ('mission-ai-feature-forge-04', 1, 'arjun', 'Sometimes the signal is not in any single feature -- it is in the relationship between two of them. An interaction feature captures that on purpose, instead of hoping the model finds it by accident.'),
  ('mission-ai-feature-forge-04', 2, 'arjun', 'Cluster Zero''s sessions do not stand out on request_count alone, or on session_duration alone. It is the ratio between them -- requests per minute -- that looks unusual.'),
  ('mission-ai-feature-forge-04', 3, 'arjun', 'Build request_count divided by session_duration as its own feature, and a relationship that was invisible in the raw columns becomes something a simple model can actually pick up on.'),

  ('mission-ai-feature-forge-05', 1, 'arjun', 'session_start is stored as a raw timestamp -- useless to a model exactly as written. Time features pull structure out of it: hour of day, day of week, and recency, how long since some reference event.'),
  ('mission-ai-feature-forge-05', 2, 'arjun', 'Cyclical patterns need special handling too. Hour 23 and hour 0 are one hour apart in reality, but a plain number treats them as almost maximally far apart -- so time-of-day features often get encoded as a pair of values that wrap around correctly.'),
  ('mission-ai-feature-forge-05', 3, 'arjun', 'Cluster Zero''s sessions cluster suspiciously in a narrow overnight window. That pattern only shows up once session_start is actually turned into usable time features.'),

  ('mission-ai-feature-forge-06', 1, 'arjun', 'Echo also logs a free-text session_note on some interactions -- unstructured text a model cannot touch directly.'),
  ('mission-ai-feature-forge-06', 2, 'byte', 'I can pull structure out of it without full language understanding: note length, whether it contains specific keywords, even just a count of how often certain terms appear across the log. Crude, but it works.'),
  ('mission-ai-feature-forge-06', 3, 'arjun', 'Crude is fine. We are not trying to read Echo''s mind, we are trying to give a model something numeric to compare. Cluster Zero''s notes, when they exist at all, are unusually short and repeat one term almost every time.'),

  ('mission-ai-feature-forge-07', 1, 'arjun', 'About a third of Echo''s log rows are missing device_class entirely -- not zero, not "unknown," just absent. That absence might itself mean something.'),
  ('mission-ai-feature-forge-07', 2, 'arjun', 'The lazy fix is silently filling every gap with a default value and moving on. The better fix is filling the gap and adding a second feature -- a plain 0/1 flag recording that the value was missing in the first place.'),
  ('mission-ai-feature-forge-07', 3, 'arjun', 'If missingness correlates with Cluster Zero, silently imputing it destroys the exact signal we are trying to find. Keeping the flag preserves it.'),

  ('mission-ai-feature-forge-08', 1, 'arjun', 'By now the pipeline has produced dozens of candidate features. Not all of them earn a place in the final model.'),
  ('mission-ai-feature-forge-08', 2, 'byte', 'Redundant features add noise without adding information -- two columns measuring almost the same thing. Irrelevant features add noise with no information at all. Feature selection means removing both, deliberately, not by accident.'),
  ('mission-ai-feature-forge-08', 3, 'arjun', 'Here is a draft selection script. Something in it is wrong -- find it before it goes anywhere near a real model.'),

  ('mission-ai-feature-forge-09', 1, 'arjun', 'Leakage is the single most dangerous mistake in this whole Act -- a feature that accidentally contains information the model would not actually have at prediction time.'),
  ('mission-ai-feature-forge-09', 2, 'arjun', 'The classic trap: fitting a scaler, an encoder, or a feature-selection step on the entire dataset before splitting it into train and test. Test data influences the transform, the transform influences training, and your evaluation numbers lie to you.'),
  ('mission-ai-feature-forge-09', 3, 'arjun', 'A leakage-safe pipeline fits every transform on training data only, then applies that same fitted transform to test data without ever looking at it again.'),

  ('mission-ai-feature-forge-10', 1, 'arjun', 'Every technique this Act taught -- transforms, encoders, selection -- has to run in the same order, the same way, every single time. Doing that by hand invites exactly the kind of leakage bug we just covered.'),
  ('mission-ai-feature-forge-10', 2, 'byte', 'scikit-learn''s Pipeline chains transform steps together into one object. Fit it once on training data, and every step -- scaling, encoding, selection -- gets fit only on that training data, in the right order, automatically.'),
  ('mission-ai-feature-forge-10', 3, 'arjun', 'Here is a draft pipeline. One line breaks the leakage-safety we just spent an entire mission building. Find it.'),

  ('mission-ai-feature-forge-11', 1, 'arjun', 'One pipeline, start to finish: raw Echo log in, leakage-safe features out, a model trained on those features, evaluated honestly on data it never touched during fitting.'),
  ('mission-ai-feature-forge-11', 2, 'byte', 'And it has to be reproducible -- same code, same data, same random seed, same result. Anything else means the pipeline cannot actually be trusted to run twice.'),
  ('mission-ai-feature-forge-11', 3, 'arjun', 'Put the stages in the right order, and this is the whole Act, assembled into one real system.'),

  ('mission-ai-feature-forge-12', 1, 'maya', 'Everything this Act taught, assembled into one system, right now. Not another notebook -- Cipher Division''s first pipeline meant to actually run in production.'),
  ('mission-ai-feature-forge-12', 2, 'arjun', 'Three things need to check out before I trust it with Cluster Zero: no leakage in the features it selected, honest reproducibility, and whether it actually flags the cluster the way it is supposed to.'),
  ('mission-ai-feature-forge-12', 3, 'arjun', 'Walk through all three. If they hold, this Arc ends with something real instead of another one-off experiment.'),
  ('mission-ai-feature-forge-12', 4, 'maya', 'And they do hold. This is Cipher Division''s first genuinely production-shaped system -- reproducible, leakage-checked, and able to flag Cluster Zero automatically instead of waiting for someone to notice it by hand.'),
  ('mission-ai-feature-forge-12', 5, 'maya', 'Every model built this Arc, however good, still needed a person to decide what it was allowed to see. What comes next learns its own features directly -- starting from the smallest possible unit of that idea, a single artificial neuron.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-feature-forge-01-o1', 'mission-ai-feature-forge-01', 1, 'Define the gap', 'State what actually separates a raw field from an engineered feature.'),
  ('mission-ai-feature-forge-01-o2', 'mission-ai-feature-forge-01', 2, 'Find the roughest raw field', 'Identify which raw field in Echo''s log needs the most engineering work before a model could use it.'),

  ('mission-ai-feature-forge-02-o1', 'mission-ai-feature-forge-02', 1, 'Fix the skew', 'Choose the correct transform for a heavily right-skewed numeric feature.'),
  ('mission-ai-feature-forge-02-o2', 'mission-ai-feature-forge-02', 2, 'Match the technique', 'Match each numeric transformation to the situation it fits.'),

  ('mission-ai-feature-forge-03-o1', 'mission-ai-feature-forge-03', 1, 'Pick the right encoding', 'Choose the correct encoding for a categorical field with no natural order.'),
  ('mission-ai-feature-forge-03-o2', 'mission-ai-feature-forge-03', 2, 'Sort order from no-order', 'Sort each categorical field into ordinal-appropriate or one-hot-appropriate.'),

  ('mission-ai-feature-forge-04-o1', 'mission-ai-feature-forge-04', 1, 'Define the idea', 'State what an interaction feature actually captures.'),
  ('mission-ai-feature-forge-04-o2', 'mission-ai-feature-forge-04', 2, 'Build the right ratio', 'Identify the interaction feature that would make Cluster Zero''s behavior visible.'),

  ('mission-ai-feature-forge-05-o1', 'mission-ai-feature-forge-05', 1, 'Know what time features extract', 'Identify what a time feature is actually built to extract from a raw timestamp.'),
  ('mission-ai-feature-forge-05-o2', 'mission-ai-feature-forge-05', 2, 'Match raw signal to technique', 'Match each raw time-related signal to the feature-engineering technique that fits it.'),

  ('mission-ai-feature-forge-06-o1', 'mission-ai-feature-forge-06', 1, 'Know the technique', 'Identify a valid way to turn free text into a usable numeric feature.'),
  ('mission-ai-feature-forge-06-o2', 'mission-ai-feature-forge-06', 2, 'Find the most useful signal', 'Identify which text-derived signal best separates Cluster Zero from normal sessions.'),

  ('mission-ai-feature-forge-07-o1', 'mission-ai-feature-forge-07', 1, 'Know why the flag matters', 'State why an explicit missing indicator is better than silent imputation alone.'),
  ('mission-ai-feature-forge-07-o2', 'mission-ai-feature-forge-07', 2, 'Spot the risky imputation', 'Find the evidence showing missingness itself is likely meaningful here.'),

  ('mission-ai-feature-forge-08-o1', 'mission-ai-feature-forge-08', 1, 'Know the goal', 'State why feature selection matters even after good features have been engineered.'),
  ('mission-ai-feature-forge-08-o2', 'mission-ai-feature-forge-08', 2, 'Debug the selection script', 'Find the line in Arjun''s draft feature selection script that introduces a real bug.'),

  ('mission-ai-feature-forge-09-o1', 'mission-ai-feature-forge-09', 1, 'Spot the leak', 'Find the evidence describing a real leakage risk in a proposed feature.'),
  ('mission-ai-feature-forge-09-o2', 'mission-ai-feature-forge-09', 2, 'Define leakage-safe', 'State what makes a pipeline leakage-safe.'),

  ('mission-ai-feature-forge-10-o1', 'mission-ai-feature-forge-10', 1, 'Know what a Pipeline buys you', 'State the main benefit of chaining steps into a scikit-learn Pipeline instead of running them by hand.'),
  ('mission-ai-feature-forge-10-o2', 'mission-ai-feature-forge-10', 2, 'Debug the pipeline', 'Find the line in the draft pipeline code that reintroduces a leakage risk.'),

  ('mission-ai-feature-forge-11-o1', 'mission-ai-feature-forge-11', 1, 'Order the pipeline', 'Put the end-to-end pipeline stages in the order they actually run.'),
  ('mission-ai-feature-forge-11-o2', 'mission-ai-feature-forge-11', 2, 'Judge reproducibility', 'Determine whether a pipeline run counts as reproducible.'),

  ('mission-ai-feature-forge-12-o1', 'mission-ai-feature-forge-12', 1, 'Validate the feature choice', 'Judge whether a proposed feature for the production pipeline is leakage-safe.'),
  ('mission-ai-feature-forge-12-o2', 'mission-ai-feature-forge-12', 2, 'Confirm reproducibility', 'Judge whether the pipeline run meets the bar for reproducibility.'),
  ('mission-ai-feature-forge-12-o3', 'mission-ai-feature-forge-12', 3, 'Confirm the flag', 'Judge whether the assembled pipeline correctly flags Cluster Zero automatically.'),
  ('mission-ai-feature-forge-12-o4', 'mission-ai-feature-forge-12', 4, 'Close the Arc', 'Having judged the feature choice, the reproducibility, and the flagging behavior, confirm Cipher Division''s first production-shaped pipeline is ready to close out this Arc.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-feature-forge-01-o1-c1', 'mission-ai-feature-forge-01-o1', 1, 'multiple_choice', 'Which best describes the difference between a raw field and an engineered feature?', '{"question":"Which best describes the difference between a raw field and an engineered feature?","options":[{"id":"a","text":"There is no real difference, the words are interchangeable"},{"id":"b","text":"A raw field is whatever a system happened to log; an engineered feature is a transformed input chosen because it carries signal a model can use"},{"id":"c","text":"A raw field is always a number, a feature is always text"},{"id":"d","text":"Features are only used in deep learning, not classical models"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-feature-forge-01-o2-c1', 'mission-ai-feature-forge-01-o2', 1, 'investigation', 'Which raw field most urgently needs feature engineering before a model can use it?', '{"evidence":[{"id":"e1","label":"session_start_raw","detail":"Stored as an unparsed string like 2026-08-03T02:14:11Z, with no numeric structure a model can compare directly"},{"id":"e2","label":"cluster_flag","detail":"Already a clean binary 0/1 column produced by Act 11''s clustering work"},{"id":"e3","label":"response_latency_ms","detail":"Already a clean numeric column in milliseconds"}],"question":"Which raw field most urgently needs feature engineering before a model can use it?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-feature-forge-02-o1-c1', 'mission-ai-feature-forge-02-o1', 1, 'multiple_choice', 'Request counts per session range from 1 to 40,000, with most sessions under 20. Which transform helps most before feeding this into a model?', '{"question":"Request counts per session range from 1 to 40,000, with most sessions under 20. Which transform helps most before feeding this into a model?","options":[{"id":"a","text":"Leave it as-is, raw counts are always fine"},{"id":"b","text":"Apply a log transform to compress the long right tail"},{"id":"c","text":"Convert it to a categorical variable with one category per exact value"},{"id":"d","text":"Delete all sessions above 20 requests"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-feature-forge-02-o2-c1', 'mission-ai-feature-forge-02-o2', 1, 'drag_and_drop', 'Match each numeric transformation to the situation it fits.', '{"items":[{"id":"i1","text":"Response latency ranges from 10ms to 50,000ms with a long right tail"},{"id":"i2","text":"Two features on wildly different scales (age in years, income in dollars) feeding one distance-based model"},{"id":"i3","text":"A continuous account age in days feature that should become ordered groups like new, established, veteran"}],"targets":[{"id":"t1","label":"Log transform"},{"id":"t2","label":"Scaling / normalization"},{"id":"t3","label":"Binning"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),

  ('mission-ai-feature-forge-03-o1-c1', 'mission-ai-feature-forge-03-o1', 1, 'multiple_choice', 'interaction_type has values like query, upload, config_change, logout -- no natural order among them. Which encoding fits?', '{"question":"interaction_type has values like query, upload, config_change, logout -- no natural order among them. Which encoding fits?","options":[{"id":"a","text":"Ordinal encoding, ranked alphabetically"},{"id":"b","text":"One-hot encoding, one column per category"},{"id":"c","text":"Leave it as raw text strings"},{"id":"d","text":"Convert each category to a random number"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-feature-forge-03-o2-c1', 'mission-ai-feature-forge-03-o2', 1, 'drag_and_drop', 'Sort each categorical field into ordinal-appropriate or one-hot-appropriate.', '{"items":[{"id":"i1","text":"severity: low, medium, high, critical"},{"id":"i2","text":"region: us-east, us-west, eu-central, ap-south"},{"id":"i3","text":"subscription_tier: free, standard, premium"},{"id":"i4","text":"device_class: desktop, mobile, api-client, unknown"}],"targets":[{"id":"t1","label":"Ordinal encoding (real order)"},{"id":"t2","label":"One-hot encoding (no real order)"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),

  ('mission-ai-feature-forge-04-o1-c1', 'mission-ai-feature-forge-04-o1', 1, 'multiple_choice', 'An interaction feature is best described as...', '{"question":"An interaction feature is best described as...","options":[{"id":"a","text":"Any feature involving user interaction logs specifically"},{"id":"b","text":"A new feature built by combining two or more existing features to capture a relationship neither carries alone"},{"id":"c","text":"A duplicate copy of an existing feature"},{"id":"d","text":"A feature that only works in deep learning models"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-feature-forge-04-o2-c1', 'mission-ai-feature-forge-04-o2', 1, 'investigation', 'Which feature would actually make Cluster Zero''s sessions stand out?', '{"evidence":[{"id":"e1","label":"request_count alone","detail":"Distribution overlaps almost completely with normal sessions -- no separation"},{"id":"e2","label":"session_duration alone","detail":"Distribution also overlaps almost completely with normal sessions"},{"id":"e3","label":"requests per minute (request_count / session_duration)","detail":"Cluster Zero sessions cluster tightly at a rate roughly 8x higher than normal sessions -- clear separation"}],"question":"Which feature would actually make Cluster Zero''s sessions stand out?"}'::jsonb, '{"requiredEvidenceIds":["e3"]}'::jsonb),

  ('mission-ai-feature-forge-05-o1-c1', 'mission-ai-feature-forge-05-o1', 1, 'multiple_choice', 'A time feature extracted from a raw timestamp is best described as...', '{"question":"A time feature extracted from a raw timestamp is best described as...","options":[{"id":"a","text":"The timestamp string itself, unchanged"},{"id":"b","text":"A derived value like hour of day, day of week, or time since a reference event, chosen because it may carry signal"},{"id":"c","text":"A random number assigned per timestamp"},{"id":"d","text":"Something only relevant to video or audio data"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-feature-forge-05-o2-c1', 'mission-ai-feature-forge-05-o2', 1, 'drag_and_drop', 'Match each raw time-related signal to the feature-engineering technique that fits it.', '{"items":[{"id":"i1","text":"A single session_start timestamp string"},{"id":"i2","text":"Hour-of-day values where 23 and 0 need to be treated as close together"},{"id":"i3","text":"Time since the account''s very first recorded interaction"}],"targets":[{"id":"t1","label":"Extract calendar components"},{"id":"t2","label":"Cyclical encoding"},{"id":"t3","label":"Recency feature"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),

  ('mission-ai-feature-forge-06-o1-c1', 'mission-ai-feature-forge-06-o1', 1, 'multiple_choice', 'Which of these is a valid way to turn a free-text field into a feature a model can use?', '{"question":"Which of these is a valid way to turn a free-text field into a feature a model can use?","options":[{"id":"a","text":"Leave the text field completely unchanged and hope the model understands it"},{"id":"b","text":"Derive numeric signals from it, such as text length, keyword presence, or term frequency"},{"id":"c","text":"Delete every row that has any text in it"},{"id":"d","text":"Convert the text to a single random number"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-feature-forge-06-o2-c1', 'mission-ai-feature-forge-06-o2', 1, 'investigation', 'Which text-derived signal most strongly separates Cluster Zero from normal sessions?', '{"evidence":[{"id":"e1","label":"Average note length","detail":"Cluster Zero notes average 6 words; normal sessions average 40 words -- notably shorter"},{"id":"e2","label":"Contains the term sync","detail":"Present in over 90% of Cluster Zero notes, versus under 5% of normal sessions -- strong separation"},{"id":"e3","label":"Contains any punctuation","detail":"Roughly the same rate in both groups -- no separation"}],"question":"Which text-derived signal most strongly separates Cluster Zero from normal sessions?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-feature-forge-07-o1-c1', 'mission-ai-feature-forge-07-o1', 1, 'multiple_choice', 'Why add a missing indicator feature instead of only imputing the missing value?', '{"question":"Why add a missing indicator feature instead of only imputing the missing value?","options":[{"id":"a","text":"It has no real benefit, imputing alone is always sufficient"},{"id":"b","text":"Because the fact that a value was missing can itself carry signal, which silent imputation erases"},{"id":"c","text":"Because models cannot process any numeric data without one"},{"id":"d","text":"Because it makes the dataset file smaller"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-feature-forge-07-o2-c1', 'mission-ai-feature-forge-07-o2', 1, 'investigation', 'Which evidence shows that missingness itself likely carries signal, not just noise?', '{"evidence":[{"id":"e1","label":"Missingness by cluster","detail":"device_class is missing in 78% of Cluster Zero rows, versus 4% of normal rows -- a large, consistent gap"},{"id":"e2","label":"Storage format","detail":"The log is stored as newline-delimited JSON"},{"id":"e3","label":"Column order","detail":"device_class happens to be the last column in the raw log schema"}],"question":"Which evidence shows that missingness itself likely carries signal, not just noise?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-feature-forge-08-o1-c1', 'mission-ai-feature-forge-08-o1', 1, 'multiple_choice', 'Why keep applying feature selection even after features have been carefully engineered?', '{"question":"Why keep applying feature selection even after features have been carefully engineered?","options":[{"id":"a","text":"More features always make a model strictly better, so selection is unnecessary"},{"id":"b","text":"Redundant or irrelevant features add noise, overfitting risk, and cost without adding real signal"},{"id":"c","text":"It only matters for deep learning models"},{"id":"d","text":"To make the code shorter, nothing else"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-feature-forge-08-o2-c1', 'mission-ai-feature-forge-08-o2', 1, 'code_debugging', 'Find the line that lets the label leak into the selected feature set.', '{"language":"python","code":"correlations = df.corrwith(df[\"cluster_zero_label\"])\nselected = correlations[correlations.abs() > 0.1].index.tolist()\nX_selected = df[selected]\ny = df[\"cluster_zero_label\"]\nmodel.fit(X_selected, y)","question":"Which line lets the label leak into the selected feature set?"}'::jsonb, '{"requiredLineIds":["correlations = df.corrwith(df[\"cluster_zero_label\"])"]}'::jsonb),

  ('mission-ai-feature-forge-09-o1-c1', 'mission-ai-feature-forge-09-o1', 1, 'investigation', 'Which proposed feature would leak the answer directly into the model?', '{"evidence":[{"id":"e1","label":"Proposed feature: cluster_zero_label","detail":"The exact value the model is trying to predict, accidentally left in the feature set"},{"id":"e2","label":"Proposed feature: request_count","detail":"A raw count available at prediction time, no leakage risk"},{"id":"e3","label":"Proposed feature: session_duration","detail":"Known once a session ends, available at prediction time, no leakage risk"}],"question":"Which proposed feature would leak the answer directly into the model?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-feature-forge-09-o2-c1', 'mission-ai-feature-forge-09-o2', 1, 'multiple_choice', 'A leakage-safe pipeline is best described as one where...', '{"question":"A leakage-safe pipeline is best described as one where...","options":[{"id":"a","text":"Every transform is fit on the full dataset, including test data, for maximum accuracy"},{"id":"b","text":"Every transform is fit only on training data, then applied unchanged to test data"},{"id":"c","text":"No transforms are applied at all"},{"id":"d","text":"The test set is used to pick the best-looking features before training"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-feature-forge-10-o1-c1', 'mission-ai-feature-forge-10-o1', 1, 'multiple_choice', 'The main benefit of chaining feature steps into a scikit-learn Pipeline is...', '{"question":"The main benefit of chaining feature steps into a scikit-learn Pipeline is...","options":[{"id":"a","text":"It makes the code run on a GPU automatically"},{"id":"b","text":"It guarantees every step is fit only on training data and applied consistently, reducing the risk of leakage"},{"id":"c","text":"It removes the need for a train/test split entirely"},{"id":"d","text":"It automatically deletes irrelevant features"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-feature-forge-10-o2-c1', 'mission-ai-feature-forge-10-o2', 1, 'code_debugging', 'Find the line that fits a transform on data that includes the test set, before the split even happens.', '{"language":"python","code":"scaler = StandardScaler()\nX_scaled = scaler.fit_transform(X)\nX_train, X_test, y_train, y_test = train_test_split(X_scaled, y, test_size=0.2)\npipeline = Pipeline([(\"scaler\", StandardScaler()), (\"model\", LogisticRegression())])\npipeline.fit(X_train, y_train)","question":"Which line fits a transform on data that includes the test set, before the split even happens?"}'::jsonb, '{"requiredLineIds":["X_scaled = scaler.fit_transform(X)"]}'::jsonb),

  ('mission-ai-feature-forge-11-o1-c1', 'mission-ai-feature-forge-11-o1', 1, 'drag_and_drop', 'Put the end-to-end pipeline stages in the order they actually run.', '{"items":[{"id":"i1","text":"Split raw log into train and test sets"},{"id":"i2","text":"Fit feature transforms (scalers, encoders, imputers) on training data only"},{"id":"i3","text":"Apply the fitted transforms to both training and test data"},{"id":"i4","text":"Train the model on transformed training data"},{"id":"i5","text":"Evaluate the model on transformed test data it never influenced"}],"targets":[{"id":"t1","label":"Step 1"},{"id":"t2","label":"Step 2"},{"id":"t3","label":"Step 3"},{"id":"t4","label":"Step 4"},{"id":"t5","label":"Step 5"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4","i5":"t5"}}'::jsonb),
  ('mission-ai-feature-forge-11-o2-c1', 'mission-ai-feature-forge-11-o2', 1, 'investigation', 'Which evidence would actually break reproducibility?', '{"evidence":[{"id":"e1","label":"Run log A","detail":"Same code, same data file, same random seed, produces the identical selected features and model coefficients on every run"},{"id":"e2","label":"Run log B","detail":"Feature selection uses a random sample of rows with no fixed seed, producing a different feature set on every run"},{"id":"e3","label":"Run log C","detail":"The pipeline was run on a faster server this week"}],"question":"Which evidence would actually break reproducibility?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-feature-forge-12-o1-c1', 'mission-ai-feature-forge-12-o1', 1, 'investigation', 'Which proposed feature would leak information the pipeline should not have at prediction time?', '{"evidence":[{"id":"e1","label":"Proposed feature: requests_per_minute","detail":"Computed only from request_count and session_duration, both fully known once a session ends and the model runs, no future information used"},{"id":"e2","label":"Proposed feature: final_cluster_zero_score","detail":"Computed by a downstream process that only exists after the review team has already flagged a session as Cluster Zero -- not available before that decision"},{"id":"e3","label":"Proposed feature: account_age_days","detail":"Known at the moment the session starts, fully available before prediction"}],"question":"Which proposed feature would leak information the pipeline should not have at prediction time?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-ai-feature-forge-12-o2-c1', 'mission-ai-feature-forge-12-o2', 1, 'investigation', 'Which evidence actually confirms the pipeline is reproducible?', '{"evidence":[{"id":"e1","label":"Pipeline run log","detail":"Fixed random seed, versioned training data snapshot, and every transform fit only on the training split -- three independent runs produce identical selected features and identical model coefficients"},{"id":"e2","label":"Ops note","detail":"The pipeline was deployed on a new server rack this week"},{"id":"e3","label":"Dashboard note","detail":"The pipeline dashboard uses a different color theme than last month''s version"}],"question":"Which evidence actually confirms the pipeline is reproducible?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-feature-forge-12-o3-c1', 'mission-ai-feature-forge-12-o3', 1, 'investigation', 'Which evidence actually confirms the pipeline flags Cluster Zero correctly, rather than just memorizing training data?', '{"evidence":[{"id":"e1","label":"Held-out evaluation","detail":"On a test set the pipeline never touched during fitting, it flags 94% of known Cluster Zero sessions and produces false positives on well under 1% of normal sessions"},{"id":"e2","label":"Training set evaluation","detail":"The pipeline flags 100% of Cluster Zero sessions it was trained on -- expected, and not meaningful evidence on its own"},{"id":"e3","label":"Manual spot-check","detail":"One analyst reviewed 5 flagged sessions and agreed with all 5"}],"question":"Which evidence actually confirms the pipeline flags Cluster Zero correctly, rather than just memorizing training data?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-feature-forge-12-o4-c1', 'mission-ai-feature-forge-12-o4', 1, 'boss_encounter', 'Having judged the feature choice, the reproducibility, and the flagging behavior, confirm Cipher Division''s first production-shaped pipeline is ready to close out this Arc.', '{"stages":[{"objectiveRef":"mission-ai-feature-forge-12-o1","label":"Validate the feature choice"},{"objectiveRef":"mission-ai-feature-forge-12-o2","label":"Confirm reproducibility"},{"objectiveRef":"mission-ai-feature-forge-12-o3","label":"Confirm the flag"}],"task":"State whether Cipher Division''s pipeline is ready: leakage-checked, reproducible, and correctly flagging Cluster Zero on data it never trained on."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-feature-forge-12-o1","mission-ai-feature-forge-12-o2","mission-ai-feature-forge-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-feature-forge-01-o1-c1', 'orientation', 'Think about what a model can directly compare or compute on, versus what a person can merely read.', 10, 1),
  ('mission-ai-feature-forge-01-o1-c1', 'solution', 'A raw field is unprocessed log output; an engineered feature is a transformed input deliberately chosen because it carries signal a model can use.', 20, 2),
  ('mission-ai-feature-forge-01-o2-c1', 'orientation', 'An unparsed string cannot be compared numerically by a model at all.', 10, 1),
  ('mission-ai-feature-forge-01-o2-c1', 'solution', 'e1: session_start_raw is stored as a raw string, with no numeric structure yet -- everything else is already numeric and usable.', 20, 2),

  ('mission-ai-feature-forge-02-o1-c1', 'orientation', 'Think about what happens to a model when a handful of extreme values sit far outside the rest of the data.', 10, 1),
  ('mission-ai-feature-forge-02-o1-c1', 'concept', 'A log transform compresses large values much more than small ones, pulling in the tail without discarding it.', 20, 2),
  ('mission-ai-feature-forge-02-o1-c1', 'solution', 'Apply a log transform -- it compresses the long right tail instead of deleting data or pretending the skew is not there.', 30, 3),
  ('mission-ai-feature-forge-02-o2-c1', 'orientation', 'Ask what each situation actually needs: less skew, comparable scale, or discrete groups.', 10, 1),
  ('mission-ai-feature-forge-02-o2-c1', 'solution', 'Latency needs a log transform to compress its tail; the mismatched scales need scaling/normalization; account age needs binning into ordered groups.', 20, 2),

  ('mission-ai-feature-forge-03-o1-c1', 'orientation', 'Ask whether the categories have any real ranking from low to high.', 10, 1),
  ('mission-ai-feature-forge-03-o1-c1', 'solution', 'One-hot encoding -- these categories have no natural order, so ranking them with ordinal encoding would invent a false relationship.', 20, 2),
  ('mission-ai-feature-forge-03-o2-c1', 'orientation', 'A category has real order only if you could sensibly say one value is more or less than another.', 10, 1),
  ('mission-ai-feature-forge-03-o2-c1', 'concept', 'severity and subscription_tier both have a genuine low-to-high progression; region and device_class do not.', 20, 2),
  ('mission-ai-feature-forge-03-o2-c1', 'solution', 'Ordinal: severity, subscription_tier. One-hot: region, device_class.', 30, 3),

  ('mission-ai-feature-forge-04-o1-c1', 'orientation', 'Think about what two separate numbers can reveal only when compared to each other, like speed being distance over time.', 10, 1),
  ('mission-ai-feature-forge-04-o1-c1', 'solution', 'An interaction feature is built by combining existing features to capture a relationship neither one carries alone.', 20, 2),
  ('mission-ai-feature-forge-04-o2-c1', 'orientation', 'Neither raw feature alone separated the cluster, so the answer is not either one alone.', 10, 1),
  ('mission-ai-feature-forge-04-o2-c1', 'solution', 'e3: requests per minute, the ratio of the two raw features, is where the separation actually shows up.', 20, 2),

  ('mission-ai-feature-forge-05-o1-c1', 'orientation', 'A raw timestamp string carries no structure a model can compare numerically on its own.', 10, 1),
  ('mission-ai-feature-forge-05-o1-c1', 'solution', 'A time feature is a derived value like hour of day, day of week, or time since a reference event, deliberately extracted for its potential signal.', 20, 2),
  ('mission-ai-feature-forge-05-o2-c1', 'orientation', 'Ask what each raw signal needs: a component pulled out, a wraparound handled, or a distance from a reference point measured.', 10, 1),
  ('mission-ai-feature-forge-05-o2-c1', 'concept', 'Hour 23 and hour 0 are adjacent in real time but far apart as plain numbers -- that specific problem is what cyclical encoding solves.', 20, 2),
  ('mission-ai-feature-forge-05-o2-c1', 'solution', 'A single timestamp -> extract calendar components. Wraparound hours -> cyclical encoding. Time since a reference event -> recency feature.', 30, 3),

  ('mission-ai-feature-forge-06-o1-c1', 'orientation', 'The raw text string itself is not something a model can compare numerically.', 10, 1),
  ('mission-ai-feature-forge-06-o1-c1', 'solution', 'Deriving numeric signals like length, keyword presence, or term frequency is how free text becomes a usable feature.', 20, 2),
  ('mission-ai-feature-forge-06-o2-c1', 'orientation', 'Look for the largest gap between Cluster Zero and normal sessions, not just any difference.', 10, 1),
  ('mission-ai-feature-forge-06-o2-c1', 'solution', 'e2: the term sync appears in over 90% of Cluster Zero notes versus under 5% elsewhere -- by far the strongest separation.', 20, 2),

  ('mission-ai-feature-forge-07-o1-c1', 'orientation', 'Ask what gets thrown away if a gap is filled and the fact it was ever a gap is not recorded anywhere.', 10, 1),
  ('mission-ai-feature-forge-07-o1-c1', 'solution', 'Missingness itself can be informative, and silently imputing over it erases that information.', 20, 2),
  ('mission-ai-feature-forge-07-o2-c1', 'orientation', 'Compare the missing rate inside the cluster to the missing rate outside it.', 10, 1),
  ('mission-ai-feature-forge-07-o2-c1', 'solution', 'e1: device_class is missing far more often in Cluster Zero rows than normal ones -- that gap itself is a real signal, not noise.', 20, 2),

  ('mission-ai-feature-forge-08-o1-c1', 'orientation', 'Think about what happens to a model''s ability to generalize when it is fed near-duplicate or noise columns.', 10, 1),
  ('mission-ai-feature-forge-08-o1-c1', 'solution', 'Redundant and irrelevant features add noise, overfitting risk and cost, without adding real signal.', 20, 2),
  ('mission-ai-feature-forge-08-o2-c1', 'orientation', 'Correlation was computed against the whole dataframe, not just the candidate features.', 10, 1),
  ('mission-ai-feature-forge-08-o2-c1', 'concept', 'The label column will always correlate perfectly with itself, so if it is not excluded first, it can end up selected as its own predictor.', 20, 2),
  ('mission-ai-feature-forge-08-o2-c1', 'solution', 'The first line is the bug -- it never excludes the label column from df before correlating, so the label can select itself as a feature.', 30, 3),

  ('mission-ai-feature-forge-09-o1-c1', 'orientation', 'Ask which feature would simply not exist yet at the moment the model needs to make a prediction.', 10, 1),
  ('mission-ai-feature-forge-09-o1-c1', 'solution', 'e1: including cluster_zero_label itself as a feature leaks the answer directly -- it is what the model is supposed to predict.', 20, 2),
  ('mission-ai-feature-forge-09-o2-c1', 'orientation', 'Think about which data the model is allowed to have seen before it is evaluated.', 10, 1),
  ('mission-ai-feature-forge-09-o2-c1', 'solution', 'Fit every transform only on training data, then apply that same fitted transform to test data without refitting on it.', 20, 2),

  ('mission-ai-feature-forge-10-o1-c1', 'orientation', 'Think about what happens when a person has to remember to run five steps in the right order, every time, by hand.', 10, 1),
  ('mission-ai-feature-forge-10-o1-c1', 'solution', 'A Pipeline guarantees every step is fit only on training data and applied the same way every time, cutting leakage risk.', 20, 2),
  ('mission-ai-feature-forge-10-o2-c1', 'orientation', 'Look for a fit_transform call that happens before the train/test split.', 10, 1),
  ('mission-ai-feature-forge-10-o2-c1', 'concept', 'Scaling the full dataset before splitting lets information from the test set influence the transform used on training data.', 20, 2),
  ('mission-ai-feature-forge-10-o2-c1', 'solution', 'The scaler.fit_transform(X) line is the bug -- it fits the scaler on the whole dataset before the split, leaking test information into training.', 30, 3),

  ('mission-ai-feature-forge-11-o1-c1', 'orientation', 'Nothing can be fit before the split happens, or the split stops meaning anything.', 10, 1),
  ('mission-ai-feature-forge-11-o1-c1', 'concept', 'Transforms get fit once on training data, then applied unchanged to both sets before anything is trained or scored.', 20, 2),
  ('mission-ai-feature-forge-11-o1-c1', 'solution', 'Split, fit transforms on training data only, apply transforms to both sets, train the model, evaluate on the untouched test set.', 30, 3),
  ('mission-ai-feature-forge-11-o2-c1', 'orientation', 'Reproducibility means literally identical results on repeated runs, not just similar hardware.', 10, 1),
  ('mission-ai-feature-forge-11-o2-c1', 'solution', 'e2: an unseeded random sample changes the feature set on every run -- that breaks reproducibility, regardless of the code or data staying the same.', 20, 2),

  ('mission-ai-feature-forge-12-o1-c1', 'orientation', 'Ask which feature could only exist after a human has already made the exact decision the model is supposed to make on its own.', 10, 1),
  ('mission-ai-feature-forge-12-o1-c1', 'solution', 'e2: final_cluster_zero_score only exists after a human review has already flagged the session -- using it as a feature would leak the answer.', 20, 2),
  ('mission-ai-feature-forge-12-o2-c1', 'orientation', 'Reproducibility is about identical results across runs, not about hardware or appearance.', 10, 1),
  ('mission-ai-feature-forge-12-o2-c1', 'solution', 'e1: a fixed seed, versioned data, and training-only fitting producing identical results across three runs is the actual reproducibility evidence.', 20, 2),
  ('mission-ai-feature-forge-12-o3-c1', 'orientation', 'Training-set performance alone never proves a model generalizes -- it can just mean memorization.', 10, 1),
  ('mission-ai-feature-forge-12-o3-c1', 'solution', 'e1: strong performance on data the pipeline never trained on is the real evidence it generalizes, not the training-set number.', 20, 2),
  ('mission-ai-feature-forge-12-o4-c1', 'orientation', 'Look at what all three checks were really testing: not any of Echo''s answers, but the pipeline''s honesty about them.', 15, 1),
  ('mission-ai-feature-forge-12-o4-c1', 'solution', 'The pipeline is leakage-safe, reproducible, and correctly flags Cluster Zero on unseen data -- it is ready. Cipher Division''s first production-shaped system, and Arc II''s real capstone, holds.', 25, 2);
